# Tufts family businesses (owner request 2026-11-03). Public sources only.
BROOKS = "Charles Brooks, <em>History of the Town of Medford</em> (1855)"
BROOKS_URL = "https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A2001.05.0104%3Achapter%3D11&amp;force=y"
BK = lambda pg: BROOKS + f', p. {pg}. <a href="{BROOKS_URL}">Text (Perseus)</a>'
TIDE_URL = "https://tidemillinstitute.org/Portal/docs/US-MA-076_Medford_Tufts_Cutter.pdf"
NT_TIDE_PDF = "https://tidemillinstitute.org/Portal/docs/US-MA-066_Charlestown_Tufts.pdf"
SAWYER_OC = "Timothy T. Sawyer, <em>Old Charlestown: Historical, Biographical, Reminiscent</em> (Boston, 1902)"
SAWYER_IA = "https://archive.org/details/oldcharlestownhi1902sawy"
SW = lambda pgs: SAWYER_OC + f', p. {pgs}. <a href="{SAWYER_IA}">Internet Archive</a>'
MHR11_IA = "https://archive.org/details/medfordhistoricav9v12medf"
MHR21_IA = "https://archive.org/details/medfordhistoricv21v26medf"
def BIZ(id_, h, who, what, where, when, body):
    return (f'<section id="{id_}"><h2>{h}</h2><p class="bizmeta"><strong>Tufts:</strong> {who} &middot; <strong>Business:</strong> {what} &middot; '
            f'<strong>Location:</strong> {where} &middot; <strong>Dates:</strong> {when}</p>{body}</section>{{DIV}}')
PR = lambda s, n: f'<a href="{{P}}profiles/{s}.html">{n}</a>'
SPOT_POND = (
'<h3 id="spot-pond-dam">Spot Pond mill and dam, Malden, 1794&ndash;1800</h3>\n'
'<p><strong>Tufts association.</strong> Samuel Tufts owned &ldquo;a certain mill, mill-dam, and mill-site, situated on a certain brook there, called Spot-Pond Brook, in Malden,&rdquo; the brook that flows out of Spot Pond in Stoneham. In his plea he called it &ldquo;an ancient mill and mill-dam, and mill privilege,&rdquo; held as his own estate in fee simple on February 17, 1794, and kept up by him for more than six years. John Buckman, whose sixteen acres the dam flooded, sued for damages. On appeal the Supreme Judicial Court found that &ldquo;Samuel Tufts the defendant, has had, and now has, a prescriptive right to keep up the dam, in the same situation and height, as in his plea he has declared.&rdquo;</p>\n'
'<p class="cite"><em>John Buckman v. Samuel Tufts</em>, Supreme Judicial Court, in James Sullivan, <em>The History of Land Titles in Massachusetts</em> (Boston, 1801), pp. 280&ndash;282. <a href="https://books.google.com/books?id=IGdGAAAAYAAJ">Google Books</a>. See also &ldquo;Medford&rsquo;s Water Supply,&rdquo; <em>The Medford Historical Register</em>, vol. XIII, no. 3 (July 1910), p. 61. <a href="https://archive.org/details/medfordhistoricv13v16medf">Volume scan (Internet Archive)</a></p>\n'
+ UNV("Which Samuel Tufts owned the mill is not stated in the case report, and the date of the verdict (October 1800) comes from the Medford Historical Register, not from Sullivan&rsquo;s text.")
+ '\n')
BIZ_HTML = (
'<section id="about"><p>Long before the college that bears the name, the Tufts family earned its living from the clay, water and roads of the Mystic valley: ferrying, brickmaking, tanning, milling, fishing, distilling, printing and, later, pharmacy. Each entry below names the family member, the trade, the place and the dates, quoting the printed page. Doubtful identifications are marked Unverified. See also <a href="{P}places.html#mystic-river">the Mystic River</a> and <a href="{P}places.html#homesteads">Homesteads</a>.</p></section>{DIV}'
+ BIZ("ferry", "The Charlestown&ndash;Malden Ferry", "Peter Tufts (the immigrant, 1617&ndash;1700)", "Ferry", "Mystic River, between Charlestown and Malden", "1646&ndash;47",
  Q("He kept the Ferry between Charlestown and Malden with his brother-in-law, Bridges, in 1646-7", BOOTH + f', part 1, p. 21. <a href="{BOOTH_URL}2">Perseus</a>')
  + '<p>The ferry crossed the Mystic. Booth adds that Peter was the largest landholder in Malden when he died in 1700. See <a href="{P}generations/colonial.html#immigrant">Peter Tufts the Immigrant</a>.</p>'
  + UNV("The ferry&rsquo;s exact landing places and the length of his tenure. Booth found no earlier record of him than 1646&ndash;47."))
+ BIZ("brick-yard-pasture", "Brick-yard Pasture, Medford", PR("simon-tufts-11-1","Dr. Simon Tufts"), "Brickmaking land", "North of Dr. Tufts&rsquo;s house, Medford", "Bought March 26, 1761",
  Q("At a later date, say 1750, bricks were made on land directly north of Dr. Tufts's house. &hellip; This land, called Brick-yard Pasture, was owned by Rev. Matthew Byles, of Boston, and sold by him to Dr. Simon Tufts, March 26, 1761.", BK(355))
  + '<p>Dr. Tufts&rsquo;s house stood at Medford Square (see <a href="{P}places.html#homesteads">Homesteads</a>).</p>'
  + UNV("Brooks records the purchase of the land, not that Dr. Tufts made bricks himself. By 1761 the elder Dr. Simon had died (1747), so the buyer was presumably the younger Dr. Simon (1726&ndash;1786). Not confirmed by deed."))
+ BIZ("hall-brickyards", "Stephen Hall&rsquo;s brickyards", "Samuel Tufts, jun.", "Brickmaking (occupant)", "Medford", "1785",
  Q("In 1785, Stephen Hall willed &lsquo;the brick-yards now in the occupation of Thomas Bradshaw, and Samuel Tufts, jun.&rsquo;", BK(355))
  + UNV(f'Which Samuel Tufts this was. Candidates on this site include {PR("samuel-tufts-15-3","Samuel Tufts (15-3)")} and {PR("samuel-tufts-41-2","Samuel Tufts 2d (41-2)")}; neither is confirmed.'))
+ BIZ("farmington-brick-mills", "Brickmaking and the first mills at Farmington Falls, Maine", PR("francis-tufts-20-1","Rev. Francis Tufts (1744&ndash;1833)"), "Brickmaking; mills", "Farmington and Farmington Falls, Maine (then part of Massachusetts)", "Mills by 1790s; brick house 1810",
  Q("the bricks were manufactured by the builder, a professional brickmaker among other accomplishments, from clay taken from the banks of the Sandy River a few hundred yards west of the site.", 'National Register nomination, Tufts House, Farmington (NRIS 79000130, 1979), section 8, p. 3. <a href="https://npgallery.nps.gov/NRHP/GetAsset/NRHP/79000130_text">NPS NPGallery</a>')
  + '<p>The same nomination says he &ldquo;built and owned the first mills at Farmington Falls.&rdquo; His profile, from the family record, dates the first mill to 1788. See <a href="{P}places.html#farmington-tufts-house">Tufts House, Farmington</a>.</p>'
  + UNV("The kind of mills (grist or saw) and the exact year. The sources differ slightly."))
+ BIZ("fountain-yards", "The Fountain Yards", "William, Hutchinson and Benjamin Tufts", "Brickmaking", "Near the &ldquo;Fountain House,&rdquo; about eighty rods east of Gravelly Bridge, Medford (toward the Malden line)", "Early; discontinued before 1855",
  Q("Messrs. William Tufts, Thomas Bradshaw, Hutchinson Tufts, Benjamin Tufts, and Sylvanus Blanchard were the manufacturers in that locality. These yards have been discontinued within our day.", BK(356))
  + '<p>The Medford Historical Society places the Fountain Yards along Fulton Street from Forest Street to the Malden line. <a href="https://medfordhistorical.org/medford-history/about-medford/making-bricks-in-medford/">Medford Historical Society</a></p>'
  + UNV(f'Which William Tufts this was (for example {PR("william-tufts-13-6","Lieut. William Tufts, 13-6")} or {PR("william-tufts-40-2","William Tufts Jr., 40-2")}). Brooks gives no dates for the individual makers.'))
+ BIZ("sodom-yards", "The &ldquo;Sodom&rdquo; Brickyards", "Isaac, Jonathan and Ebenezer Tufts, brothers; later Seth Tufts and his son Seth", "Brickmaking", "South side of the Mystic, near the Middlesex Canal, south-south-east of Rock Hill (between Summer and George Streets, on Brickyard Lane)", "18th century to shortly before 1855",
  Q("As the familiar and improper sobriquet of Sodom was early given to that part of Medford which lies south of the river, the brick-yards, opened by the brothers Isaac, Jonathan, and Ebenezer Tufts, obtained the local name. After these gentlemen came Seth Tufts, who, with his son Seth, carried on the business till recently. These yards were situated near Middlesex Canal and the river, about south-south-east from Rock Hill.", BK(356))
  + '<p>The street location is from the <a href="https://medfordhistorical.org/medford-history/about-medford/making-bricks-in-medford/">Medford Historical Society</a>. Medford bricks were carried by lighter down the Mystic to Boston.</p>'
  + UNV(f'Whether these brothers are the Revolutionary soldiers {PR("isaac-tufts-36-10","Isaac (36-10)")}, {PR("jonathan-tufts-36-8","Jonathan (36-8)")} and {PR("ebenezer-tufts-36-7","Ebenezer (36-7)")} of the same family number. The names and family grouping fit, but Brooks does not give their dates.'))
+ BIZ("pottery", "James Tufts and Son, potters", "James Tufts and son", "Pottery", "Medford", "Late 18th or early 19th century",
  Q("Mr. James Tufts and Son carried on for many years the pottery business.", BK(353))
  + UNV("Which James Tufts this was, and the site of the pottery. Brooks gives neither."))
+ BIZ("tannery", "Tan-yard and leather works", "Nathan Tufts", "Tanning and butchering; leather manufacture", "Medford (corner south-east of Whitmore&rsquo;s Bridge), later Charlestown", "Before 1855",
  Q("The first tan-yard in Medford was on the corner lot south-east of Whitmore's Bridge. &hellip; It was last owned by Mr. Nathan Tufts and Mr. Jonathan Brooks, in company. When they sold it, Mr. Tufts moved to Charlestown, and became the most extensive manufacturer of leather in the State.", BK(353))
  + Q("Nathan, the youngest son of Nathan, Sr., was also a resident of Charlestown after his boyhood, and was an extensive butcher and tanner there.", BOOTH + f', part 2, p. 21. <a href="{BOOTH_URL}7">Perseus</a>')
  + '<p>Booth adds that he owned &ldquo;the large farms around the Powder House and Walnut hill&rdquo; (p. 21). See <a href="{P}places.html#powder-house">the Powder House</a>. Sawyer&rsquo;s account of this Charlestown butcher and tanner, who died in October 1835 aged seventy-one, includes the tide mill and mill pond at the Neck. See <a href="{P}businesses.html#nathan-tufts-tide-mill">Tide mill of Nathan Tufts</a> and his <a href="{P}profiles/nathan-tufts-1764.html">profile</a>.</p>'
  + UNV("That Brooks&rsquo;s Medford tan-yard partner and Booth&rsquo;s and Sawyer&rsquo;s Charlestown butcher and tanner are the same Nathan Tufts. The match is likely, but Sawyer does not name the Medford yard."))
+ BIZ("nathan-tufts-tide-mill", "Tide mill of Nathan Tufts, Charlestown",
  PR("nathan-tufts-1764","Nathan Tufts (c. 1764&ndash;October 1835)"),
  "Tide mill (grist); mill pond; tannery and lumber wharf",
  "Tufts Mill Pond, Mystic River side of Charlestown Neck, just below present Sullivan Square (approx. 42.3864&deg; N, 71.0717&deg; W)",
  "Built in Nathan Tufts&rsquo;s lifetime (he died 1835); pond and an abutting tannery acquired by the city in 1891 and filled by 1905",
  FIG("tide-mill-nathan-tufts-charlestown.jpg", "hfig-flow")
  + '<p>A lantern slide in the Boston Public Library&rsquo;s Charlestown collection, titled &ldquo;Tide mill of Nathan Tufts,&rdquo; shows a cluster of wooden, shingled mill buildings on an unpaved lot. Across the gable of the nearer building a painted sign reads &ldquo;NATHAN TUFTS &amp; SON.&rdquo;</p>'
  + '<p>The mill belonged to ' + PR("nathan-tufts-1764","Nathan Tufts") + ', brother of Daniel Tufts and Deacon Amos Tufts, and son of Nathan Tufts, a cordwainer and Medford farmer.</p>'
  + Q("One of the sons of this Peter was Nathan Tufts, by trade a cordwainer, but chiefly occupied as a farmer in Medford. He was the father of Daniel, Deacon Amos, and Nathan Tufts, who for the greater part of their lives were prominent citizens of the old town and among its leading business men.", SW(162))
  + '<p>The younger Nathan, Sawyer wrote, &ldquo;was a noted man in the old town.&rdquo; He began as a butcher and packed beef on a large scale, then became widely known for the quality of the sole-leather he tanned. He kept a wharf on the Mystic-river side of Charlestown, dealing in wood and lumber, &ldquo;and a grist-mill made a part of his establishment.&rdquo;</p>'
  + Q("His tannery and wharf were on the Mystic-river side of the town, and a good many of the town's people found steady employment there. Besides this, he built the Mill-pond at the Neck, and was connected with Abel Fitz in the grain and meal business there. He also started a new tannery there, and carried it on as long as he lived. It was afterwards sold to Chester Guild &amp; Sons", SW("167&ndash;168"))
  + FIG("map-charlestown-1848-tufts-mill-pond.jpg", "hfig-flow")
  + '<p>In another passage Sawyer places that pond &ldquo;by the side of Maiden Bridge,&rdquo; with &ldquo;the mills &hellip; grinding, slowly perhaps, but surely&rdquo; (' + SW(463) + '). The 1848 city plan labels the rectangular basin on the Mystic shore &ldquo;Tufts Mill Pond,&rdquo; next to the bridge, and shows the earlier Charlestown Mill Pond separately, south of the Neck. The <em>Medford Historical Register</em> later called Nathan&rsquo;s works &ldquo;a tide-mill just below Sullivan square.&rdquo; <span class="cite">&ldquo;Why Mystic?,&rdquo; <em>The Medford Historical Register</em>, vol. XXI, no. 3 (July 1918), p. 53. <a href="' + MHR21_IA + '">Volume scan (Internet Archive)</a></span></p>'
  + '<p>The two ponds are easily confused. On a map of the Revolutionary period, the Register noted, &ldquo;the area now covered by railroad tracks, freight houses etc., [was] the Charlestown Mill Pond. A later map would show the Tufts&rsquo; Mill Pond, where is now the Charlestown Playground.&rdquo; <span class="cite">&ldquo;The Second Battle of Bunker&rsquo;s Hill,&rdquo; <em>The Medford Historical Register</em>, vol. XI, no. 2 (April 1908), p. 43. <a href="' + MHR11_IA + '">Volume scan (Internet Archive)</a></span> It was the older dam, not Nathan&rsquo;s later pond, that Major Knowlton and about a hundred men crossed on the night of January 8, 1776, &ldquo;the Mill Dam which lays between Cobble Hill and Bunker&rsquo;s Hill,&rdquo; in a raid on houses still standing outside the burned town. The <em>New-England Chronicle</em> printed the account on January 11, 1776, quoted in the same Register article (pp. 43&ndash;44).</p>'
  + '<p>Nathan lived in the house on Chelsea Street first built and occupied by Aaron Putnam, later known as the home of Dr. Lambert (' + SW("168, 171") + '). He died in October 1835, aged seventy-one, and had no children. By his will, after provision for his wife&mdash;his widow Mary later testified in a suit over the estate&mdash;and a few bequests, among them $1,000 to the Bunker Hill Monument Association, the bulk of his property went to his nephews and nieces, the children of Daniel and Deacon Amos (' + SW(168) + '). Among those heirs on this site are ' + PR("william-tufts-1802","William Tufts (1802&ndash;1862)") + ', ' + PR("edward-tufts-1806","Edward Tufts (1806&ndash;1875)") + ', and the next generation, ' + PR("george-f-tufts-1825","George F. Tufts (1825&ndash;1920)") + ' and ' + PR("alfred-tufts-1829","Alfred Tufts (1829&ndash;1882)") + '. See also the <a href="{P}businesses.html#tannery">tan-yard and leather works</a> and the homestead note on <a href="{P}places.html#homesteads">Places</a>.</p>'
  + '<p>A Tide Mill Institute compilation, citing Seasholes, states that the city acquired Tufts Mill Pond and an abutting tannery in 1891 and finished filling the site in 1905, making Charlestown Playground, renamed the John J. Ryan, Jr., Playground in 1942. The same compilation gives the approximate location 42.3864&deg; N, 71.0717&deg; W, near Sullivan Square. <span class="cite">Tide Mill Institute, &ldquo;MA Charlestown, Tufts Mill.&rdquo; <a href="' + NT_TIDE_PDF + '">PDF</a></span></p>'
  + UNV("The sign &ldquo;NATHAN TUFTS &amp; SON&rdquo; cannot be read as naming a child of this Nathan, who, Sawyer says, had no children (p. 168). A later firm, Nathan Tufts &amp; Sons, grain dealers, occupied a Warren Avenue wharf and store as successors to Wesson &amp; Gary (Sawyer, p. 82); that Nathan, accidentally killed October 20, 1887, was the son of a different Nathan Tufts (Daniel&rsquo;s son, the brick-maker, who died August 1, 1872) (Sawyer, p. 163). Whether the mill sign names a relative, a successor, or a trading style is not established. The lantern slide is dated only ca. 1850&ndash;1925. The 1891 acquisition, 1905 filling, and 1942 renaming rest on the Tide Mill Institute compilation citing Seasholes; the original Seasholes page has not been checked. Claims that the earlier Charlestown mills date from the 1640s, had a pond of about thirty acres, that the 1776 raid was ordered by General Washington, or that those older mills were later tied to the Middlesex Canal, have not been verified in the sources used here. (The 1848 plan does show the Middlesex Canal immediately west of Tufts Mill Pond.)"))
+ BIZ("tide-mill", "Sandy Bank tide mill, 1746", "Dr. Simon Tufts, &ldquo;Esq., physician&rdquo; (the elder, 1700&ndash;1747)", "Gristmill (landowner and party to the agreement)", "Gravelly Creek, Medford", "Agreement of Feb. 20, 1746",
  Q("Articles of agreement were concluded, Feb. 20, 1746, between Richard Sprague, cooper, Samuel Page, yeoman, Simon Tufts, Esq., physician, &hellip; all of Medford, and owners of land", BK(394))
  + '<p>Brooks says Dr. Tufts and others bound themselves &ldquo;never to obstruct the free flow of water to the mill&rdquo; (p. 394).</p>')
+ BIZ("turnpike-mills", "Saw and grist mills on the Medford Turnpike", "William Tufts and Edward Tufts (with Gershom Cutter)", "Saw and grist milling", "Medford Turnpike (now Mystic Avenue)", "By 1848; sold to Gershom Cutter about 1845&ndash;48",
  Q("&lsquo;the owners of the saw and grist mills on the turnpike,&rsquo; William Tufts, Edward Tufts and Gershom Cutter", f'Tide Mill Institute, &ldquo;Medford, Massachusetts: Tufts-Cutter Mill,&rdquo; compiled extracts. <a href="{TIDE_URL}">PDF</a>')
  + UNV("This is a compilation; its original printed source and page are not yet confirmed. The compilation says Gershom Cutter bought &ldquo;the Tufts mill&rdquo; in 1845, but it names William and Edward Tufts as owners in the 1848 agreement. Which William and Edward these were is not known."))
+ BIZ("fishing", "Mystic River fishing rights", "Jonathan, Isaac, Charles, Simon and Seth Tufts", "Fishery (town fishing rights)", "Mystic River, Medford", "About 1803",
  Q("Among the earliest fishermen were John Cutter, Jonathan Tufts, and Benjamin Teel. In 1803, Cutter paid sixty-five dollars, Tufts thirteen dollars, and Teel thirteen dollars, for the right of fishing. &hellip; Isaac Tufts fished from the Bridge to Rock Hill", BK(385))
  .replace("</blockquote>\n", "</blockquote>\n" + SPOT_POND, 1)
  + '<p>Brooks adds that &ldquo;Charles, Simon, and Seth Tufts are there&rdquo; in the records (p. 385).</p>'
  + UNV("Which Jonathan, Isaac, Charles, Simon and Seth Tufts these were."))
+ BIZ("distillery", "Medford distilling", "Fitch Tufts", "Distilling (Medford rum)", "Medford", "Late 18th to early 19th century",
  Q("The business has been carried on by Messrs. Andrew Hall, Benjamin Hall, John Bishop, Nathaniel Hall, Fitch Tufts, Joseph Swan, Hall and Manning, and Joseph Hall.", BK(391))
  + UNV("Fitch Tufts&rsquo;s dates and the location of his distillery."))
+ BIZ("printer", "Edmund Tufts, Printer", "Edmund Tufts, son of Joseph Tufts (1760&ndash;1819)", "Printing", "The Peter Tufts of Winter Hill homestead, Somerville", "About 1842&ndash;1851 and after",
  Q("Edmund was intimately connected with the early history of this town, and his sign on the old house, &lsquo;Edmund Tufts, Printer,&rsquo; is still remembered. For some years he did the printing for the new town of Somerville and its inhabitants, and we find his name on most of the early town reports. He issued a Somerville Directory in 1851, a pamphlet of thirty-two pages.", BOOTH + f', part 2, p. 24. <a href="{BOOTH_URL}7">Perseus</a>')
  + '<p>The 1851 directory was reprinted in the same volume of <em>Historic Leaves</em> (p. 25). See <a href="{P}places.html#homesteads">Homesteads</a>.</p>'
  + UNV("His birth and death dates and the years of the press. Somerville was set off in 1842, which suggests the start date; that is an inference."))
+ BIZ("james-w-tufts", "James W. Tufts, apothecary and soda-fountain maker", "James Walker Tufts (1835&ndash;1902), son of Leonard Tufts of Charlestown", "Pharmacy and drug stores; Arctic soda apparatus; silver-plated ware", "Somerville Avenue near the Bleachery; Medford; Boston (Washington and Hanover Streets)", "1856&ndash;1895",
  Q("Leonard, who lived in Charlestown, was the father of James W. Tufts, who was at one time an apothecary in Somerville avenue, near the Bleachery. Mr. Tufts has since become well-known as a manufacturer of soda-water apparatus.", BOOTH + f', part 2, p. 24. <a href="{BOOTH_URL}7">Perseus</a>')
  + '<p>He was apprenticed at fifteen to Samuel Kidder and Company, druggists of Charlestown, and opened his own pharmacy in Somerville in 1856. He later had stores in Medford, Boston, Winchester and Woburn, then sold the stores to make his Arctic Soda Apparatus. In 1891 his firm merged into the American Soda Fountain Company, which he headed. He also built the Bunker Hill Terraces tenements in Charlestown (1890) and later founded Pinehurst, N.C. <span class="cite">(<a href="https://www.ncpedia.org/biography/tufts-james-walker">NCpedia</a>)</span> From 1875 his firm also made silver-plated wares. <span class="cite">(<a href="https://www.si.edu/object/soda-glass-holder%3Anmah_1059718">Smithsonian</a>)</span> Booth places him in the line of John Tufts (b. 1755) of the Peter and Oliver Tufts House.</p>'
  + UNV("NCpedia gives his apprenticeship at fifteen; another account says sixteen."))
+ BIZ("albert-c-tufts", "Albert C. Tufts, druggist", "Albert C. Tufts", "Pharmacy", "Sacramento, Calif.", "City directories 1869&ndash;1902",
  '<p>His record is on the <a href="{P}generations/19th-century.html#albert-c-tufts">19th Century</a> page, drawn from Sacramento city directories.</p>'
  + UNV("His tie to the Massachusetts families is not established."))
+ BIZ("tufts-express-chicago", "Tufts Express &amp; Van Co., Chicago", "William Tufts (b. about 1888) and family; O. J. Tufts, manager (1925)", "Express, moving and household-goods storage; later furniture sales", "4341 W. Madison St., later also 4444 W. Madison St., West Side of Chicago", "About 1900/1902 to at least 1933",
  '<p>On the far West Side of Chicago, a schoolboy who would not stay in school built a moving business from the family horse and a sawed-off lunch car. The <em>Chicago Daily Tribune</em> told his story in 1908:</p>'
  + Q("Today, at 20 years old, William Tufts is a west side business man, head of the establishment, with his father and brother working for him.", f'Hollis W. Field, &ldquo;Plays Hookey and Succeeds,&rdquo; <em>Chicago Daily Tribune</em>, Aug. 23, 1908, Sunday magazine. <a href="https://archive.org/details/per_chicago-daily-tribune_1908-08-23_67_34">Internet Archive</a>')
  + Q("That was the real beginning of the Tufts express and van business &hellip; There are ten horses and eleven wagons in the Tufts establishment now", "Same article")
  + '<p>The article dates the start to &ldquo;about 1902,&rdquo; on &ldquo;the eastern edge of Austin,&rdquo; and says he had just bought three auto trucks for $3,000 apiece. The 1911 Lakeside directory lists a Tufts at &ldquo;4341 W Madison&rdquo; among Chicago expressmen <span class="cite">(<a href="https://archive.org/details/lakesideannualdi1911unse">Lakeside Annual Directory, 1911</a>)</span>. The trade journal <em>Distribution &amp; Warehousing</em> lists &ldquo;Tufts Express, 4341 West Madison. Estd. 1900.&rdquo; <span class="cite">(Dec. 1920, <a href="https://archive.org/details/sim_distribution_1920-12_19_12">Internet Archive</a>)</span> In January 1925 it announced that the firm &ldquo;will soon enter the furniture warehousing business&rdquo; in a six-story fireproof building on West Madison Street. Its listing that month reads &ldquo;Tufts Express &amp; Van Co., 4341 W. Madison. O. J. Tufts, Mgr.&rdquo; <span class="cite">(<a href="https://archive.org/details/sim_distribution_1925-01_24_1">Internet Archive</a>)</span></p>'
  + '<p>From 1926 the <em>Tribune</em>&rsquo;s classified pages carry its ads at the new address. One reads &ldquo;TUFT&rsquo;S FIREPROOF &amp; VAN Co., 4444 W. MADISON-ST.&rdquo; <span class="cite">(Apr. 12, 1929, <a href="https://archive.org/details/per_chicago-daily-tribune_1929-04-12_88_88">Internet Archive</a>)</span> Another, &ldquo;Can be seen at Tufts Storage, 4444 W. Madison. Open evenings and Sunday&rdquo;, comes from the 1932 furniture-sale ads <span class="cite">(Feb. 5, 1932, <a href="https://archive.org/details/per_chicago-daily-tribune_1932-02-05_91_31">Internet Archive</a>)</span>. The ads continue into 1933.</p>'
  + UNV("Whether this Chicago family descends from the Massachusetts Tufts lines on this site. The parents of William Tufts are not named in any source found. Who O. J. Tufts was, and the full given name of the 1911 directory entry (printed indistinctly as &ldquo;Oin B&rdquo;), are also not confirmed. Note: Pending further work."))
+ '<section id="not-found"><h2>Trades Searched, Not Yet Found</h2>'
  + UNV("<strong>Shipbuilding.</strong> Medford&rsquo;s shipyards (1803&ndash;1873) were run by Magoun, Turner, Lapham, Stetson, Sprague and James, Waterman and Ewell, Curtis, Foster and others. No Tufts shipyard owner has been found yet in Brooks or the Old Ship Street district history. A Tufts may have worked as a carpenter or owned shares in a ship; this is unchecked. <strong>Silversmithing.</strong> No colonial Tufts silversmith has been found. The only Tufts silver found so far is James W. Tufts&rsquo;s silver plate (from 1875). <strong>Taverns.</strong> None is yet documented for a Tufts.")
  + '</section>'
)
page("businesses.html", "Businesses | Tufts Lineage &amp; Legacy", "Places", "Businesses", "The trades of the Tufts family, colonial era to the 19th century", BIZ_HTML)

MYSTIC_HTML = '''<section id="mystic-river"><h2>The Mystic River</h2>
<p>The Mystic runs through the family&rsquo;s whole New England story. The first Peter kept its ferry. His descendants dug clay along its banks, fished it, milled on its creeks, and farmed the slopes above it in Medford, Charlestown and Malden.</p>
''' + TA("Every association below is cited; see <a href=\'{P}businesses.html\'>Businesses</a> for the full entries.") + '''
<ul>
<li><strong>Ferry (Penny Ferry):</strong> Peter Tufts kept the Charlestown&ndash;Malden ferry in 1646&ndash;47 (Booth, part 1, p. 21), succeeding Philip Drinker in early 1647 (Corey, <em>History of Malden</em>, p. 85, n. 53). Corey calls it the Penny Ferry, superseded by Malden Bridge in 1787; the name &ldquo;Tufts Landing&rdquo; is not found in any source checked. <a href="{P}businesses.html#ferry">Entry</a> &middot; <a href="{P}profiles/peter-tufts-1617.html">Profile</a></li>
<li><strong>Brickyards on the south bank:</strong> the &ldquo;Sodom&rdquo; yards of Isaac, Jonathan and Ebenezer Tufts, then Seth Tufts and his son, &ldquo;near Middlesex Canal and the river&rdquo; (Brooks, p. 356). <a href="{P}businesses.html#sodom-yards">Entry</a></li>
<li><strong>Brickyards on the north side:</strong> the Fountain Yards of William, Hutchinson and Benjamin Tufts (Brooks, p. 356), and Dr. Simon Tufts&rsquo;s Brick-yard Pasture (Brooks, p. 355).</li>
<li><strong>Fishing:</strong> Jonathan Tufts held fishing rights in 1803, and &ldquo;Isaac Tufts fished from the Bridge to Rock Hill.&rdquo; One fishing district ran &ldquo;from the bridge to the beach opposite James Tufts's barn&rdquo; (Brooks, p. 385). <a href="{P}businesses.html#fishing">Entry</a></li>
<li><strong>Mills:</strong> Dr. Simon Tufts was a party to the 1746 Sandy Bank tide-mill agreement on Gravelly Creek (Brooks, p. 394). William and Edward Tufts owned mills on the Medford Turnpike (Tide Mill Institute compilation). <a href="{P}profiles/nathan-tufts-1764.html">Nathan Tufts (c. 1764&ndash;1835)</a> built Tufts Mill Pond and a tide mill on the Mystic side of Charlestown Neck (Sawyer, pp. 167, 463). <a href="{P}businesses.html#nathan-tufts-tide-mill">Entry</a> &middot; <a href="{P}profiles/nathan-tufts-1764.html">Profile</a></li>
<li><strong>Medford bank homes:</strong> the Peter Tufts House on Riverside Avenue (<a href="#homesteads">Homesteads</a>), and the Royall farm, where Peter Tufts (b. 1753) settled early (Booth, part 2, p. 22).</li>
<li><strong>Charlestown bank:</strong> Peter Tufts Jr.&rsquo;s 1818 <em>Plan of Charlestown Peninsula</em> maps the river frontage (<a href="#maps">Maps</a>). Nathan Tufts&rsquo;s mill pond and tide mill lay on the Mystic side of the Neck, just below present Sullivan Square. <a href="{P}businesses.html#nathan-tufts-tide-mill">Entry</a> &middot; <a href="{P}profiles/nathan-tufts-1764.html">Profile</a></li>
</ul>
''' + UNV("No Tufts shipyard on the Mystic has been found. The location of &ldquo;James Tufts's barn&rdquo; is not identified.") + '</section>'
_EXTRA2 = EXTRA
def EXTRA(path):
    out = _EXTRA2(path)
    if path == "places.html":
        out = '{DIV}<section id="businesses"><h2>Businesses</h2><p>The family&rsquo;s brickyards, ferry, tannery, mills, fishery, distillery, press and pharmacies each have their own entry on the <a href="{P}businesses.html">Businesses</a> page.</p></section>{DIV}' + MYSTIC_HTML + out
    L = {"profiles/simon-tufts-11-1.html": "brick-yard-pasture", "profiles/isaac-tufts-36-10.html": "sodom-yards", "profiles/jonathan-tufts-36-8.html": "sodom-yards", "profiles/ebenezer-tufts-36-7.html": "sodom-yards", "profiles/samuel-tufts-15-3.html": "hall-brickyards", "profiles/samuel-tufts-41-2.html": "hall-brickyards", "profiles/william-tufts-13-6.html": "fountain-yards", "profiles/william-tufts-40-2.html": "fountain-yards"}
    if path in L:
        out += '{DIV}<section id="business"><h2>Business</h2><p>A man of this name appears in Brooks&rsquo;s <em>History of Medford</em> in connection with the brickyards. Whether it is this man is Unverified. See <a href="{P}businesses.html#' + L[path] + '">Businesses</a>.</p></section>'
    if path in ("profiles/nathan-tufts-1764.html", "profiles/william-tufts-1802.html", "profiles/edward-tufts-1806.html", "profiles/george-f-tufts-1825.html", "profiles/alfred-tufts-1829.html"):
        out += '{DIV}<section id="business"><h2>Business</h2><p>Nathan Tufts (c. 1764&ndash;1835), the Charlestown butcher and tanner who bequeathed land to the sons of his brothers Daniel and Amos, built the mill pond at Charlestown Neck and ran a tide mill, tannery and wharf there. See <a href="{P}businesses.html#nathan-tufts-tide-mill">Tide mill of Nathan Tufts</a>.</p></section>'
    return out
